class Solution {
public:
    int minMoves(vector<int>& nums, int limit) {
        int n = nums.size();
        int L = limit;
        vector<int> diff(2 * L + 2, 0);

        for (int i = 0; i < n / 2; i++) {
            int a = nums[i];
            int b = nums[n - 1 - i];
            int lo = 1 + min(a, b);
            int hi = L + max(a, b);
            int target = a + b;

            // base: 2 moves for every sum in [2, 2L]
            diff[2] += 2;
            diff[2 * L + 1] -= 2;

            // 1-move region [lo, hi]: subtract 1
            diff[lo] -= 1;
            diff[hi + 1] += 1;

            // 0-move point [target, target]: subtract 1 more (nested inside 1-move)
            diff[target] -= 1;
            diff[target + 1] += 1;
        }

        int ans = INT_MAX;
        int cur = 0;
        for (int s = 2; s <= 2 * L; s++) {
            cur += diff[s];
            if (cur < ans) ans = cur;
        }
        return ans;
    }
};
